function Plan(cost) {
  this.cost = cost;
}
Plan.prototype.price = function () {
  return this.cost;
};
function TeamPlan(cost, seats) {
  Plan.call(this, cost);
  this.seats = seats;
}
TeamPlan.prototype = Object.create(Plan.prototype);
TeamPlan.prototype.price = function () {
  return Plan.prototype.price.call(this) * this.seats;
};
const p = new Plan(10);
const t = new TeamPlan(10, 4);
console.log(p.price(), t.price());
console.log(t instanceof Plan);
console.log(t.constructor === Plan);
console.log(Object.hasOwn(t, "cost"));
